package cn.lili.modules.community.p0.stage45;
import cn.lili.modules.community.p0.support.*;import cn.lili.modules.community.p0.stage2.*;import com.google.gson.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.support.StaticListableBeanFactory;import java.security.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import static cn.lili.modules.community.p0.support.Stage1Json.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Generated test RSA keys and synthetic official-shaped payloads only. Not real-channel evidence. */
class Stage45RealPaidSourceTest {
 static KeyPair key;static Stage45RealPaidSource source;static final Instant AT=Instant.parse("2026-11-02T09:00:00Z");
 @BeforeAll static void keys()throws Exception{var generator=KeyPairGenerator.getInstance("RSA");generator.initialize(2048);key=generator.generateKeyPair();source=new Stage45RealPaidSource(new Stage45WechatEvidence(Map.of("UNIT_RSA_PUBLIC",key.getPublic())));}
 JsonObject request(){return object(map("mode","REAL","tradeId","1","payerMemberId","2","payerOpenIdHash",digest("UNIT_OPENID".getBytes(StandardCharsets.UTF_8)),"applicationId","wx_UNIT","platformMerchantId","12345678","combineNo","UNIT_COMBINE","currency","CNY","amountCent",1001,"subOrders",List.of(map("orderId","3","storeId","4","subNo","UNIT_SUB","merchantId","12345678","subMchid","23456789","amountCent",1001))));}
 JsonObject response(){return object(map("combine_appid","wx_UNIT","combine_mchid","12345678","combine_out_trade_no","UNIT_COMBINE","combine_payer_info",map("openid","UNIT_OPENID"),"sub_orders",List.of(map("mchid","12345678","sub_mchid","23456789","out_trade_no","UNIT_SUB","transaction_id","UNIT_TRANSACTION","trade_state","SUCCESS","success_time",AT,"amount",map("total_amount",1001,"payer_amount",1001,"currency","CNY","payer_currency","CNY")))));}
 JsonObject proof(JsonObject body)throws Exception{String raw=write(body)+"\n",timestamp=String.valueOf(AT.getEpochSecond()),nonce="UNIT_NONCE";var signer=Signature.getInstance("SHA256withRSA");signer.initSign(key.getPrivate());signer.update((timestamp+"\n"+nonce+"\n"+raw+"\n").getBytes(StandardCharsets.UTF_8));return object(map("method","GET","uri","/v3/combine-transactions/out-trade-no/UNIT_COMBINE","httpStatus",200,"observedAt",AT,"body",raw,"headers",map("Wechatpay-Serial","UNIT_RSA_PUBLIC","Wechatpay-Timestamp",timestamp,"Wechatpay-Nonce",nonce,"Wechatpay-Signature",Base64.getEncoder().encodeToString(signer.sign()))));}
 @Test void signedOriginalCombineEvidenceUsesSamePaidValidationIncludingRawNewline()throws Exception{var request=request();var envelope=source.normalize(request,proof(response()));assertTrue(source.trusted(request,envelope));var facts=Stage2PaymentFacts.requireAuthenticated(envelope,request,"REAL");assertEquals(1001,facts.get("amountCent").getAsLong());assertEquals("UNIT_TRANSACTION",facts.getAsJsonArray("subOrders").get(0).getAsJsonObject().get("transactionId").getAsString());assertThrows(Stage1Exception.class,()->Stage2PaymentFacts.require(envelope,request));}
 @Test void validSignatureCannotRepairWrongOriginalIdentityAmountOrChildSet()throws Exception{for(int i=0;i<7;i++){var body=response();var sub=body.getAsJsonArray("sub_orders").get(0).getAsJsonObject();switch(i){case 0->body.addProperty("combine_appid","other");case 1->body.getAsJsonObject("combine_payer_info").addProperty("openid","other");case 2->sub.addProperty("sub_mchid","other");case 3->sub.getAsJsonObject("amount").addProperty("payer_amount",1000);case 4->sub.remove("success_time");case 5->body.getAsJsonArray("sub_orders").add(sub.deepCopy());default->sub.addProperty("trade_state","NOTPAY");}var signed=proof(body);assertThrows(RuntimeException.class,()->source.normalize(request(),signed),"variant "+i);}}
 @Test void tamperedUnboundOrStaleProofAndMissingRealAdapterFailClosed()throws Exception{var request=request();var valid=source.normalize(request,proof(response()));valid.getAsJsonObject("paid").addProperty("amountCent",1);assertFalse(source.trusted(request,valid));var changed=proof(response());changed.addProperty("body",write(map("state","PAID")));assertThrows(Stage1Exception.class,()->source.normalize(request,changed));var stale=proof(response());stale.addProperty("observedAt",AT.plusSeconds(301).toString());assertThrows(Stage1Exception.class,()->source.normalize(request,stale));var empty=new StaticListableBeanFactory();var service=new Stage45PaidEvidence(mock(PersistentPaymentMock.class),empty.getBeanProvider(Stage45RealPaidSource.class));assertFalse(service.trusted("REAL",request,source.normalize(request,proof(response()))));}
}
